import { Component, OnInit, inject } from '@angular/core';
import { forkJoin } from 'rxjs';
import { StudentApiService, studentApiError } from '../../core/student-api.service';
import { CourseSummary, GradeCourse } from '../../core/student-api.models';

interface Row {
  code: string;
  title: string;
  credits: number;
  total: number | null;
}

/** Academic summary + the unofficial transcript PDF generated by the backend. */
@Component({
  selector: 'sb-reports',
  standalone: true,
  template: `
    <div class="page-header">
      <h1>Reports</h1>
      <button class="btn-primary" (click)="download()" [disabled]="downloading">
        {{ downloading ? 'Preparing…' : 'Download unofficial transcript (PDF)' }}
      </button>
    </div>

    @if (error) {
      <div class="sa-error" style="margin-bottom: 16px">{{ error }}</div>
    }

    <div class="card sa-card">
      <div class="card-head">
        <span class="card-title">Academic summary</span>
        <span class="text-muted" style="font-size: 12.5px">{{ totalCredits() }} ECTS enrolled</span>
      </div>
      @if (rows.length === 0) {
        <p class="text-muted">No courses yet.</p>
      } @else {
        <table>
          <thead><tr><th>Code</th><th>Course</th><th>Credits</th><th>Current grade</th></tr></thead>
          <tbody>
            @for (r of rows; track r.code) {
              <tr>
                <td class="text-muted">{{ r.code }}</td>
                <td>{{ r.title }}</td>
                <td class="text-muted">{{ r.credits }}</td>
                <td>{{ r.total !== null ? r.total + '%' : '—' }}</td>
              </tr>
            }
          </tbody>
        </table>
      }
    </div>
  `,
})
export class ReportsComponent implements OnInit {
  private api = inject(StudentApiService);

  rows: Row[] = [];
  downloading = false;
  error: string | null = null;

  ngOnInit(): void {
    forkJoin({ courses: this.api.courses(), grades: this.api.grades() }).subscribe({
      next: ({ courses, grades }) => (this.rows = this.build(courses, grades)),
      error: (err) => (this.error = studentApiError(err, 'Could not load your academic summary.')),
    });
  }

  private build(courses: CourseSummary[], grades: GradeCourse[]): Row[] {
    return courses.map((c) => ({
      code: c.code,
      title: c.title,
      credits: c.credits,
      total: grades.find((g) => g.courseId === c.id)?.totalPercent ?? null,
    }));
  }

  totalCredits(): number {
    return this.rows.reduce((s, r) => s + r.credits, 0);
  }

  download(): void {
    this.downloading = true;
    this.error = null;
    this.api.transcript().subscribe({
      next: (blob) => {
        this.downloading = false;
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'studybox-unofficial-transcript.pdf';
        a.click();
        setTimeout(() => URL.revokeObjectURL(url), 10_000);
      },
      error: (err) => {
        this.downloading = false;
        this.error = studentApiError(err, 'Could not generate the transcript.');
      },
    });
  }
}
